---刷新装备道具
function CardProgressionEquipmentLevelUpFinishNode:RefreshEquipmentGoods()
    local dojo = self:GetCurDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(dojo.equipmentId)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = dojo, goodsId = dojo.equipmentId, isShowNo = false})
    end
    CfUtils.FillText(self.TxtEquipName, goodsVo.name)
end

---刷新等级
function CardProgressionEquipmentLevelUpFinishNode:RefreshLevel()
    local befDojo = self:GetBefDojo()
    local curDojo = self:GetCurDojo()
    CfUtils.FillText(self.BeforeLv, '+' .. tostring(befDojo.level))
    CfUtils.FillText(self.AfterLv, '+' .. tostring(curDojo.level))
end

---刷新属性
function CardProgressionEquipmentLevelUpFinishNode:RefreshAttr()
    local befDojo = self:GetBefDojo()
    local curDojo = self:GetCurDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(curDojo.equipmentId)
    local equipVo = cardConfMgr:GetEquipVoById(curDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = cardConfMgr:GetBasicAttr(attrAddVo.attrId)
    local attrName = cardConfMgr:GetBasicAttrNameByType(attrAddVo.attrId)
    
    CfUtils.FillImage(self.ImgAttributeIcon, attrVo.icon)
    CfUtils.FillText(self.TxtAttrName, attrName)
    CfUtils.SetUISwitchImage(self.AttrImgBg, goodsVo.quality)
    CfUtils.FillText(self.AfterAttrNum, attribute_format(attrAddVo.isConversion, befDojo.mainAttrNum))
    CfUtils.FillText(self.BeforeAttrNum, attribute_format(attrAddVo.isConversion, curDojo.mainAttrNum))
end

---显示战力变化
function CardProgressionEquipmentLevelUpFinishNode:ShowPointChange()
    local befDojo = self:GetBefDojo()
    if checkInt(befDojo.playerCardId) == 0 then return end

    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(befDojo.playerCardId) 
    local entity = CardProgressionUtils.GenerateEntityByCardDojo(cardDojo)
    local curPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    for k, v in pairs(entity.equipPart2Dojo) do
        if checkInt(v.id) == checkInt(befDojo.id) then
            entity.equipPart2Dojo[k] = befDojo
            break
        end
    end
    local befPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    CardProgressionUtils.ChangePointToast(curPoint - befPoint)
end

---开启装备培养界面
function CardProgressionEquipmentLevelUpFinishNode:OpenCultivateEquipDialog()
    local equipDojo = self:GetCurDojo()
    Events.Broadcast(Constants.EventNames.CardProgressEquipLevelUpFinish, self:GetCurDojo())
    if checkInt(equipDojo.level) == CardProgressionConstants.EquipmentLevelUpperLimit then
        EquipUtils.EnterCultivateEquipDialog(self:GetCurDojo())
    end
end

---获取befDojo
---@return EquipDojo
function CardProgressionEquipmentLevelUpFinishNode:GetBefDojo()
    return self._befDojo
end

---获取curDojo
---@return EquipDojo
function CardProgressionEquipmentLevelUpFinishNode:GetCurDojo()
    return self._curDojo
end
